// Mock da base de convênios. Formato: { cpf:'000.000.000-00', convenio:'Unimed' }
const DB_CONVENIOS = [];
function buscarConvenio(cpf, convenioSelecionado){
  const cpfLimpo=(cpf||'').replace(/\D/g,'');
  const encontrado=DB_CONVENIOS.find(c=>c.cpf.replace(/\D/g,'')===cpfLimpo);
  if(!encontrado) return {ok:false, motivo:'CPF não encontrado na base de convênios.'};
  if(encontrado.convenio!==convenioSelecionado) return {ok:false, motivo:`Esse CPF tem convênio ${encontrado.convenio}, não ${convenioSelecionado}.`};
  return {ok:true};
}

// ─── PIX (BR Code / EMV) ─────────────────────────────────
const PIX_CHAVE='1700f03b-b5c2-4346-b071-6239be355f32';
const PIX_NOME='HENRIQUE DIAS';
const PIX_CIDADE='CARAPICUIBA';
function crc16(payload){
  let crc=0xFFFF;
  for(let i=0;i<payload.length;i++){
    crc^=payload.charCodeAt(i)<<8;
    for(let j=0;j<8;j++){
      crc=(crc&0x8000)?((crc<<1)^0x1021)&0xFFFF:(crc<<1)&0xFFFF;
    }
  }
  return crc.toString(16).toUpperCase().padStart(4,'0');
}
function emvField(id,value){
  const len=String(value.length).padStart(2,'0');
  return `${id}${len}${value}`;
}
function gerarPayloadPix(valor, txid){
  const gui=emvField('00','br.gov.bcb.pix');
  const chave=emvField('01',PIX_CHAVE);
  const merchantAccount=emvField('26',gui+chave);
  const mcc=emvField('52','0000');
  const currency=emvField('53','986');
  const amount=valor?emvField('54',Number(valor).toFixed(2)):'';
  const country=emvField('58','BR');
  const merchantName=emvField('59',PIX_NOME.slice(0,25));
  const merchantCity=emvField('60',PIX_CIDADE.slice(0,15));
  const addData=emvField('62',emvField('05',(txid||'***').slice(0,25)));
  const payloadFormat=emvField('00','01');
  const semCrc=payloadFormat+merchantAccount+mcc+currency+amount+country+merchantName+merchantCity+addData+'6304';
  return semCrc+crc16(semCrc);
}
function parsePreco(str){
  const n=(str||'').replace(/[^\d,\.]/g,'').replace(',','.');
  return parseFloat(n)||0;
}
function ehPagamentoPresencial(pagamento){
  const norm=(pagamento||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  return norm==='debito'||norm==='dinheiro';
}

