// ─── MODAIS ──────────────────────────────────────────────
// window.confirm/alert são bloqueados em iframes sandboxed, por isso os modais próprios
function showConfirmModal(msg, onOk, title){
  const overlay=$('confirm-modal-overlay'); if(!overlay){ if(onOk)onOk(); return; }
  $('confirm-modal-title').textContent = title||'Confirmar ação';
  $('confirm-modal-msg').textContent = msg;
  overlay.classList.add('active');
  const okBtn=$('confirm-modal-ok'), cancelBtn=$('confirm-modal-cancel');
  const cleanup=()=>{ overlay.classList.remove('active'); okBtn.onclick=null; cancelBtn.onclick=null; };
  okBtn.onclick=()=>{ cleanup(); if(onOk) onOk(); };
  cancelBtn.onclick=cleanup;
}
function showAlertModal(msg, onClose, title){
  const overlay=$('alert-modal-overlay'); if(!overlay){ if(onClose)onClose(); return; }
  $('alert-modal-title').textContent = title||'Aviso';
  $('alert-modal-msg').textContent = msg;
  overlay.classList.add('active');
  const okBtn=$('alert-modal-ok');
  const cleanup=()=>{ overlay.classList.remove('active'); okBtn.onclick=null; };
  okBtn.onclick=()=>{ cleanup(); if(onClose) onClose(); };
}

function $(id) { return document.getElementById(id); }
function set(id, val) { const el=$(id); if(el) el.textContent=val; }
function showError(id, msg) { const el=$(id); if(!el)return; el.textContent=msg; el.style.display='block'; }
function hideError(id)      { const el=$(id); if( el) el.style.display='none'; }
function formatCpf(v) {
  return v.replace(/\D/g,'').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2').slice(0,14);
}
function cpfValido(cpf){
  const n=(cpf||'').replace(/\D/g,'');
  if(n.length!==11) return false;
  if(/^(\d)\1{10}$/.test(n)) return false; // 111.111.111-11, 000.000.000-00 etc.
  let soma=0;
  for(let i=0;i<9;i++) soma+=parseInt(n[i],10)*(10-i);
  let resto=(soma*10)%11; if(resto===10||resto===11) resto=0;
  if(resto!==parseInt(n[9],10)) return false;
  soma=0;
  for(let i=0;i<10;i++) soma+=parseInt(n[i],10)*(11-i);
  resto=(soma*10)%11; if(resto===10||resto===11) resto=0;
  if(resto!==parseInt(n[10],10)) return false;
  return true;
}
function formatPhone(v){
  const d=v.replace(/\D/g,'').slice(0,11);
  if(d.length<=10) return d.replace(/(\d{2})(\d)/,'($1) $2').replace(/(\d{4})(\d{1,4})$/,'$1-$2');
  return d.replace(/(\d{2})(\d)/,'($1) $2').replace(/(\d{5})(\d{1,4})$/,'$1-$2');
}
function senhaValida(senha){
  if(senha.length<8) return 'Senha deve ter no mínimo 8 caracteres.';
  if(!/[A-Z]/.test(senha)) return 'Senha deve ter pelo menos 1 letra maiúscula.';
  if(!/[^A-Za-z0-9]/.test(senha)) return 'Senha deve ter pelo menos 1 caractere especial (ex: ! @ # $ %).';
  return null;
}
function togglePass(id,btn){
  const el=$(id); if(!el) return;
  const showing=el.type==='text';
  el.type=showing?'password':'text';
  if(btn){ btn.textContent=showing?'👁️':'🙈'; btn.classList.toggle('revealed',!showing); btn.setAttribute('aria-label',showing?'Mostrar senha':'Ocultar senha'); }
}

// ─── DISPONIBILIDADE ─────────────────────────────────────
function consultasDoDiaDoMedico(medico,data){ return DB.consultas.filter(c=>c.medico===medico&&c.data===data&&c.status==='agendada'); }
function diaCheio(medico,data){ return consultasDoDiaDoMedico(medico,data).length>=MAX_POR_DIA; }
function horariosOcupados(medico,data){ return consultasDoDiaDoMedico(medico,data).map(c=>c.hora); }
function datasDisponiveis(medico,mesInicio,anoInicio){
  const disp=new Set(), hoje=new Date(), hojeNorm=new Date(hoje.getFullYear(),hoje.getMonth(),hoje.getDate());
  for(let off=0;off<3;off++){
    let m=mesInicio+off, a=anoInicio;
    while(m>11){m-=12;a++;}
    const tot=new Date(a,m+1,0).getDate();
    for(let d=1;d<=tot;d++){
      const dt=new Date(a,m,d);
      if(dt<hojeNorm||dt.getDay()===0) continue;
      const ds=`${String(d).padStart(2,'0')}/${String(m+1).padStart(2,'0')}/${a}`;
      if(!diaCheio(medico,ds)) disp.add(ds);
    }
  }
  return disp;
}
function horarioJaPassou(dataBR,hora){
  const hojeBR=new Date().toLocaleDateString('pt-BR');
  if(dataBR!==hojeBR) return false;
  const agora=new Date();
  const [h,m]=hora.split(':').map(Number);
  return (h*60+m)<=(agora.getHours()*60+agora.getMinutes());
}
function dataJaPassou(dataBR){
  const [d,m,a]=dataBR.split('/').map(Number);
  const dataConsulta=new Date(a,m-1,d,23,59,59); // fim do próprio dia
  return dataConsulta<new Date();
}
function slotsDiaSelecionado(medico,data){ return TODOS_SLOTS.filter(t=>!horariosOcupados(medico,data).includes(t)&&!horarioJaPassou(data,t)); }

// ─── CONSULTAS (Supabase) ────────────────────────────────
function dataBRparaISO(br){ const [d,m,a]=br.split('/'); return `${a}-${m}-${d}`; }
function dataISOparaBR(iso){ const [a,m,d]=iso.split('-'); return `${d}/${m}/${a}`; }
function dataParaISO(dt){ return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`; }

function mapConsultaDoSupabase(row){
  return {
    id:row.id, pacienteCpf:row.paciente_cpf, pacienteNome:row.paciente_nome, pacienteWhatsapp:row.paciente_whatsapp,
    especialidade:row.especialidade, medico:row.medico_nome, medicoId:row.medico_id,
    data:dataISOparaBR(row.data), hora:row.hora, status:row.status,
    convenio:row.convenio, pagamento:row.pagamento, pagamentoConfirmado:row.pagamento_confirmado,
    parcelas:row.parcelas, motivo:row.motivo, valor:row.valor,
  };
}

async function carregarConsultasDoPaciente(){
  if(!currentUser) return;
  const { data, error } = await sb.from('consultas').select('*').eq('paciente_id',currentUser.id);
  if(error){ console.warn('[Prime Clinic] Erro ao carregar consultas:', error); return; }
  DB.consultas=(data||[]).map(mapConsultaDoSupabase);
}
async function carregarConsultasDoMedico(){
  if(!currentUser) return;
  const { data, error } = await sb.from('consultas').select('*').eq('medico_id',currentUser.id);
  if(error){ console.warn('[Prime Clinic] Erro ao carregar consultas:', error); return; }
  DB.consultas=(data||[]).map(mapConsultaDoSupabase);
}
// Usa uma RPC que devolve só data/hora ocupadas, sem expor dados de pacientes
async function carregarOcupacaoDoMedico(medicoId,medicoNome){
  if(!medicoId) return;
  const hoje=new Date();
  const inicio=dataParaISO(new Date(hoje.getFullYear(),hoje.getMonth(),1));
  const fim=dataParaISO(new Date(hoje.getFullYear(),hoje.getMonth()+3,0));
  const { data, error } = await sb.rpc('consultas_publicas_medico', { p_medico_id:medicoId, p_data_inicio:inicio, p_data_fim:fim });
  if(error){ console.warn('[Prime Clinic] Erro ao carregar disponibilidade:', error); return; }
  DB.consultas=(data||[]).map(r=>({ medico:medicoNome, data:dataISOparaBR(r.data), hora:r.hora, status:'agendada' }));
}

