async function goto(id){
  if((id==='screen-dashboard'||id==='screen-booking')&&!currentUser){goto('screen-login');return;}
  if(id==='screen-medico'&&(!currentUser||currentUser.role!=='medico')){goto('screen-login');return;}
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  $(id).classList.add('active');
  window.scrollTo(0,0);
  if(id==='screen-dashboard'){ await carregarConsultasDoPaciente(); renderDashboard(); }
  if(id==='screen-medico')   { await carregarConsultasDoMedico(); renderDoctorDash('todas'); }
  if(id==='screen-booking')  {resetBooking();renderDoctorList();renderCal();}
  if(id==='screen-register') limparFormularioCadastro();
}

