// ─── AUTH ────────────────────────────────────────────────
async function doLogin(){
  const email=($('login-email').value||'').trim(), senha=($('login-pass').value||'').trim();
  hideError('login-error');
  if(!email||!senha){showError('login-error','Preencha e-mail e senha.');return;}

  const { data, error } = await sb.auth.signInWithPassword({ email, password:senha });
  if(error){ showError('login-error','E-mail ou senha incorretos.'); return; }
  const { data:perfil, error:perfilErr } = await sb.from('profiles').select('*').eq('id',data.user.id).single();
  if(perfilErr||!perfil){ showError('login-error','Não encontramos seu perfil. Tente novamente.'); return; }
  currentUser={ id:data.user.id, email:data.user.email, nome:perfil.nome, cpf:perfil.cpf, role:perfil.role, crm:perfil.crm, especialidade:perfil.especialidade, whatsapp:perfil.whatsapp };
  if(currentUser.role==='medico') goto('screen-medico');
  else goto('screen-dashboard');
}
function limparFormularioCadastro(){
  ['reg-nome','reg-email','reg-cpf','reg-nasc','reg-whatsapp','reg-senha','reg-senha-confirma'].forEach(id=>{
    const el=$(id); if(el) el.value='';
  });
  hideError('reg-error');
}

async function doRegister(){
  const nome=($('reg-nome').value||'').trim(), email=($('reg-email').value||'').trim(),
        cpf=($('reg-cpf').value||'').trim(), nasc=($('reg-nasc').value||'').trim(), senha=($('reg-senha').value||'').trim(),
        senhaConfirma=($('reg-senha-confirma').value||'').trim(),
        whatsapp=($('reg-whatsapp').value||'').trim();
  hideError('reg-error');
  if(!nome||!email||!cpf||!nasc||!senha||!senhaConfirma||!whatsapp){showError('reg-error','Preencha todos os campos.');return;}
  if(!cpfValido(cpf)){showError('reg-error','CPF inválido. Confira os números digitados.');return;}
  const erroSenha=senhaValida(senha);
  if(erroSenha){showError('reg-error',erroSenha);return;}
  if(senha!==senhaConfirma){showError('reg-error','As senhas não coincidem. Digite a mesma senha nos dois campos.');return;}
  if(whatsapp.replace(/\D/g,'').length<10){showError('reg-error','Digite um WhatsApp válido, com DDD.');return;}

  const { data:cpfExiste } = await sb.rpc('cpf_existe', { p_cpf: cpf });
  if(cpfExiste){showError('reg-error','CPF já cadastrado. Faça login.');return;}
  const { data:whatsappExiste } = await sb.rpc('whatsapp_existe', { p_whatsapp: whatsapp });
  if(whatsappExiste){showError('reg-error','Esse número de WhatsApp já está cadastrado em outra conta.');return;}
  const { data, error } = await sb.auth.signUp({
    email, password:senha,
    options:{ data:{ nome, cpf, nascimento:nasc, whatsapp } } // lido pelo trigger handle_new_user para criar o perfil
  });
  if(error){ showError('reg-error', error.message&&error.message.toLowerCase().includes('already') ? 'Este e-mail já está cadastrado.' : 'Erro ao criar conta: '+error.message); return; }
  const uid=data.user&&data.user.id;
  if(data.session){
    currentUser={ id:uid, email, nome, cpf, role:'paciente', nasc, whatsapp };
    limparFormularioCadastro();
    goto('screen-dashboard');
  }else{
    limparFormularioCadastro();
    showAlertModal('Conta criada! Enviamos um e-mail de confirmação — clique no link recebido e depois faça login pra acessar sua conta.', ()=>goto('screen-login'), 'Confirme seu e-mail');
  }
}
async function doLogout(){
  await sb.auth.signOut();
  currentUser=null;
  const e=$('login-email');if(e)e.value=''; const p=$('login-pass');if(p)p.value='';
  hideError('login-error'); goto('screen-home');
}

async function doForgotPassword(){
  const email=($('forgot-email').value||'').trim();
  hideError('forgot-error'); hideError('forgot-success');
  if(!email){showError('forgot-error','Digite seu e-mail.');return;}

  const { error } = await sb.auth.resetPasswordForEmail(email, { redirectTo:window.location.href });
  if(error){ showError('forgot-error','Não foi possível enviar o e-mail: '+error.message); return; }
  $('forgot-form').style.display='none';
  showError('forgot-success', `Enviamos um link para ${email}. Abra seu e-mail e clique nele pra criar uma nova senha.`);
}

async function doResetPassword(){
  const p1=($('reset-pass1').value||'').trim(), p2=($('reset-pass2').value||'').trim();
  hideError('reset-error');
  if(!p1||!p2){showError('reset-error','Preencha os dois campos.');return;}
  const erroSenhaReset=senhaValida(p1);
  if(erroSenhaReset){showError('reset-error',erroSenhaReset);return;}
  if(p1!==p2){showError('reset-error','As senhas não coincidem.');return;}
  const { error } = await sb.auth.updateUser({ password:p1 });
  if(error){ showError('reset-error','Erro ao atualizar senha: '+error.message); return; }
  showAlertModal('Senha atualizada com sucesso! Faça login com a nova senha.', ()=>goto('screen-login'), 'Tudo certo');
}

// ─── DASHBOARD PACIENTE ──────────────────────────────────
function renderDashboard(){
  if(!currentUser) return;
  set('dash-user-name', currentUser.nome+' 👋');
  set('nav-user-name',  currentUser.nome);
  set('nav-user-initial', currentUser.nome.charAt(0).toUpperCase());
  const minhas=DB.consultas.filter(c=>c.pacienteCpf===currentUser.cpf);
  const proxima=minhas.find(c=>c.status==='agendada');
  set('dash-prox-spec', proxima?proxima.especialidade:'Nenhuma agendada');
  set('dash-prox-data', proxima?proxima.data+', '+proxima.hora:'—');
  set('dash-prox-med',  proxima?proxima.medico:'—');
  set('dash-realizadas', minhas.filter(c=>c.status==='realizada').length);
  const tbody=$('hist-tbody'); if(!tbody)return;
  tbody.innerHTML=minhas.length===0
    ?'<tr><td colspan="5" style="color:var(--muted);text-align:center;padding:1.5rem">Nenhuma consulta encontrada.</td></tr>'
    :minhas.map(c=>{
      const badgeClasse=c.status==='realizada'?'badge-green':c.status==='cancelada'?'badge-red':'badge-orange';
      const badgeTexto=c.status==='realizada'?'Realizada':c.status==='cancelada'?'Cancelada':'Agendada';
      const acao=c.status==='agendada'?`<button class="btn-cancelar" onclick="cancelarConsulta(${c.id})">✕ Cancelar</button>`:'';
      return `<tr><td>${c.especialidade}</td><td style="color:var(--muted)">${c.medico}</td><td style="color:var(--muted)">${c.data}</td><td><span class="badge ${badgeClasse}">${badgeTexto}</span></td><td>${acao}</td></tr>`;
    }).join('');
}

// ─── DASHBOARD MÉDICO ────────────────────────────────────
function renderDoctorDash(filter){
  if(!currentUser||currentUser.role!=='medico') return;
  if(filter!==undefined) doctorFilter=filter;

  const foto=(DOCTOR_PHOTOS[currentUser.nome]||{}).avatar||'';
  const navIni=$('doc-nav-initial'); if(navIni){ navIni.src=foto; navIni.alt=currentUser.nome; }
  const navNom=$('doc-nav-nome');    if(navNom) navNom.textContent=currentUser.nome;
  const avLet=$('doc-avatar-letter');if(avLet){ avLet.src=foto; avLet.alt=currentUser.nome; }
  set('doc-medico-nome', currentUser.nome);
  set('doc-medico-crm',  (currentUser.especialidade?currentUser.especialidade+' · ':'')+(currentUser.crm||''));

  document.querySelectorAll('.filter-btn').forEach(b=>b.classList.toggle('active',b.dataset.filter===doctorFilter));

  const todas=DB.consultas.filter(c=>c.medico===currentUser.nome);
  const hoje=new Date().toLocaleDateString('pt-BR');
  const emDebito=c=>ehPagamentoPresencial(c.pagamento)&&!c.pagamentoConfirmado;
  set('doc-total', todas.length);
  set('doc-hoje',  todas.filter(c=>c.data===hoje).length);
  set('doc-agend', todas.filter(c=>c.status==='agendada').length);
  set('doc-debito',todas.filter(emDebito).length);

  let lista=todas;
  if(doctorFilter==='hoje')       lista=todas.filter(c=>c.data===hoje);
  if(doctorFilter==='agendadas')  lista=todas.filter(c=>c.status==='agendada');
  if(doctorFilter==='realizadas') lista=todas.filter(c=>c.status==='realizada');
  if(doctorFilter==='debito')     lista=todas.filter(emDebito);

  lista.sort((a,b)=>{
    const ka=a.data.split('/').reverse().join('')+a.hora.replace(':','');
    const kb=b.data.split('/').reverse().join('')+b.hora.replace(':','');
    return ka.localeCompare(kb);
  });

  const container=$('consult-list'); if(!container)return;
  if(lista.length===0){ container.innerHTML='<p style="color:var(--muted);text-align:center;padding:3rem 0">Nenhuma consulta por aqui ainda.</p>'; return; }

  container.innerHTML=lista.map(c=>{
    const pendente=emDebito(c);
    const atrasada=c.status==='agendada'&&dataJaPassou(c.data);
    return `
    <div class="consult-card" id="card-${c.id}">
      <div class="consult-time">${c.hora}</div>
      <div class="consult-patient">
        <div class="consult-patient-name">${c.pacienteNome}</div>
        <div class="consult-patient-info">${c.data} · ${c.medico} · ${c.convenio} · ${c.pagamento||'—'} · ${c.valor}</div>
        ${c.motivo?`<div style="margin-top:.4rem;font-size:.8rem;color:var(--teal);background:var(--teal-light);border-radius:6px;padding:.25rem .7rem;display:inline-block">📋 ${c.motivo}</div>`:''}
        ${pendente?`<div style="margin-top:.4rem;font-size:.8rem;color:#A32D2D;background:#FCEBEB;border-radius:6px;padding:.25rem .7rem;display:inline-block">💰 Pagamento pendente</div>`:''}
        ${atrasada?`<div style="margin-top:.4rem;font-size:.8rem;color:#854F0B;background:#FAEEDA;border-radius:6px;padding:.25rem .7rem;display:inline-block">⚠️ Data já passou — finalize ou cancele</div>`:''}
      </div>
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:.5rem;margin-left:auto;flex-shrink:0">
        <span class="consult-spec">${c.especialidade}</span>
        <span class="badge ${c.status==='realizada'?'badge-green':c.status==='cancelada'?'badge-red':'badge-orange'}">${c.status==='realizada'?'✓ Realizada':c.status==='cancelada'?'✕ Cancelada':'Agendada'}</span>
        ${pendente?`<button class="btn-pagar" onclick="confirmarPagamento(${c.id})">💰 Confirmar pagamento</button>`:''}
        ${c.status==='agendada'
          ?`<div style="display:flex;gap:.4rem">
              <a class="btn-lembrete" href="javascript:void(0)" onclick="enviarLembrete(${c.id})" title="Enviar lembrete no WhatsApp do paciente">📲</a>
              <button class="btn-finalizar${pendente?' btn-finalizar-bloqueado':''}" onclick="finalizarConsulta(${c.id})" title="${pendente?'Pagamento pendente — confirme antes de finalizar':''}">${pendente?'🔒 Finalizar':'✓ Finalizar'}</button>
              <button class="btn-cancelar" onclick="cancelarConsulta(${c.id})" title="Cancelar consulta">✕ Cancelar</button>
            </div>`
          :`<span style="font-size:.7rem;color:var(--muted)">${c.status==='cancelada'?'Cancelada':'Concluída'}</span>`}
      </div>
    </div>`;
  }).join('');
}

function cancelarConsulta(id,motivoTexto){
  const c=DB.consultas.find(c=>c.id===id);
  if(!c||c.status!=='agendada') return;
  showConfirmModal(
    `Paciente: ${c.pacienteNome}\nMédico: ${c.medico}\nData: ${c.data} às ${c.hora}\n\nEssa ação não pode ser desfeita.`,
    async ()=>{
      c.status='cancelada'; renderDoctorDash(doctorFilter); renderDashboard();
      await sb.from('consultas').update({status:'cancelada'}).eq('id',c.id);
    },
    motivoTexto||'Cancelar esta consulta?'
  );
}

function confirmarPagamento(id){
  const c=DB.consultas.find(c=>c.id===id);
  if(!c) return;
  showConfirmModal(
    `Paciente: ${c.pacienteNome}\nForma de pagamento: ${c.pagamento}\nValor: ${c.valor}`,
    async ()=>{
      c.pagamentoConfirmado=true; renderDoctorDash(doctorFilter);
      await sb.from('consultas').update({pagamento_confirmado:true}).eq('id',c.id);
    },
    'Confirmar que o pagamento foi recebido?'
  );
}

function finalizarConsulta(id){
  const c=DB.consultas.find(c=>c.id===id);
  if(!c||c.status!=='agendada') return;
  if(!c.pagamentoConfirmado){
    showAlertModal(
      `${c.pacienteNome} ainda está com pagamento pendente (${c.pagamento}). Confirme o pagamento antes de finalizar a consulta.`,
      null,
      'Pagamento pendente'
    );
    return;
  }
  showConfirmModal(
    `Paciente: ${c.pacienteNome}\nEspecialidade: ${c.especialidade}\nData: ${c.data} às ${c.hora}`,
    async ()=>{
      c.status='realizada'; renderDoctorDash(doctorFilter);
      await sb.from('consultas').update({status:'realizada'}).eq('id',c.id);
    },
    'Finalizar consulta?'
  );
}

// ─── LISTA MÉDICOS ───────────────────────────────────────
function renderDoctorList(){
  const container=$('doctor-list-wrap'); if(!container)return;
  const now=new Date();
  const especFiltro=bookingState.spec;
  const lista=especFiltro?MEDICOS.filter(m=>m.especialidades.includes(especFiltro)):MEDICOS;
  const html=lista.map((m)=>{
    const i=MEDICOS.indexOf(m);
    const disp=datasDisponiveis(m.nome,now.getMonth(),now.getFullYear());
    if(disp.size===0) return '';
    const isSel=bookingState.doctor===m.nome;
    return `<div class="doctor-item${isSel?' selected':''}" id="doc-${i}" onclick="selectDoc(${i},'${m.nome.replace(/'/g,"\\'")}')"><img class="doc-ava" src="${m.foto}" alt="${m.nome}"><div style="flex:1"><div class="doc-name">${m.nome}</div><div class="doc-spec">${m.especialidade} · ${m.crm}</div></div></div>`;
  }).join('');
  container.innerHTML=html||'<p style="color:var(--muted);font-size:.875rem">Nenhum médico disponível.</p>';
}

function resetBooking(){
  currentBookingStep=1;
  const now=new Date();
  bookingState={spec:'',specPrice:'',doctor:MEDICOS[0].nome,date:'',time:'',pagamento:'Pix',month:now.getMonth(),year:now.getFullYear()};
  for(let i=1;i<=3;i++){
    const sc=$('step-'+i),si=$('step-ind-'+i);
    if(sc)sc.classList.toggle('active',i===1);
    if(si){si.classList.toggle('active',i===1);si.classList.remove('done');}
  }
  document.querySelectorAll('.spec-item').forEach(el=>el.classList.remove('selected'));
  const bn1=$('btn-next-1');if(bn1)bn1.disabled=true;
  const bn2=$('btn-next-2');if(bn2)bn2.disabled=true;
  ['sum-spec','sum-date','sum-time'].forEach(id=>{const el=$(id);if(el)el.textContent='—';});
  const sd=$('sum-doc');if(sd)sd.textContent=MEDICOS[0].nome;
  const sp=$('sum-price');if(sp)sp.textContent='—';
  if(currentUser){const av=$('bk-avatar');if(av)av.textContent=currentUser.nome.charAt(0).toUpperCase();}
  const convSel=$('conf-convenio'); if(convSel) convSel.value='Particular';
  const paySection=$('payment-method-section'); if(paySection) paySection.style.display='block';
  const convBox=$('convenio-check-box'); if(convBox){convBox.style.display='none';convBox.innerHTML='';}
  const cobertoBox=$('convenio-coberto-box'); if(cobertoBox){cobertoBox.style.display='none';cobertoBox.innerHTML='';}
  bookingState.convenioVerificado=false;
}

function selectSpec(el,name,price){
  document.querySelectorAll('.spec-item').forEach(i=>i.classList.remove('selected'));
  el.classList.add('selected');
  bookingState.spec=name;bookingState.specPrice=price;
  const bn=$('btn-next-1');if(bn)bn.disabled=false;
  const ss=$('sum-spec');if(ss)ss.textContent=name;
  const sp=$('sum-price');if(sp)sp.textContent=price;
  const medico=MEDICOS.find(m=>m.especialidades.includes(name));
  if(medico){
    const idx=MEDICOS.indexOf(medico);
    selectDoc(idx,medico.nome);
  }else{
    renderDoctorList();
  }
}

async function selectDoc(i,name){
  bookingState.doctor=name;bookingState.date='';bookingState.time='';
  renderDoctorList();
  const sd=$('sum-doc');if(sd)sd.textContent=name;
  const sdate=$('sum-date');if(sdate)sdate.textContent='—';
  const stime=$('sum-time');if(stime)stime.textContent='—';
  const bn=$('btn-next-2');if(bn)bn.disabled=true;
  const medico=MEDICOS[i];
  if(medico) await carregarOcupacaoDoMedico(medico.id,medico.nome);
  renderCal();
}

function selectPayment(tipo,el){
  document.querySelectorAll('.payment-opt').forEach(e=>e.classList.remove('selected'));
  el.classList.add('selected');
  bookingState.pagamento=tipo.charAt(0).toUpperCase()+tipo.slice(1);
  renderPaymentDetails(tipo);
}

// ─── CONVÊNIO: buscador por CPF ───────────────────────────
function onConvenioChange(){
  const sel=$('conf-convenio');
  const box=$('convenio-check-box');
  const paySection=$('payment-method-section');
  const cobertoBox=$('convenio-coberto-box');
  if(!sel||!box) return;
  bookingState.convenioVerificado=false;
  if(cobertoBox){ cobertoBox.style.display='none'; cobertoBox.innerHTML=''; }
  if(sel.value==='Particular'){
    box.style.display='none'; box.innerHTML='';
    if(paySection) paySection.style.display='block';
    return;
  }
  if(paySection) paySection.style.display='none';
  box.style.display='block';
  const cpfSugerido=(currentUser&&currentUser.cpf)?currentUser.cpf:'';
  box.innerHTML=`
    <div class="convenio-check">
      <label>Confirme o CPF do titular do convênio</label>
      <div style="display:flex;gap:.5rem">
        <input type="text" id="convenio-cpf" placeholder="000.000.000-00" maxlength="14" value="${cpfSugerido}">
        <button type="button" class="btn-outline" style="padding:.6rem 1.1rem;white-space:nowrap" onclick="verificarConvenio()">Verificar</button>
      </div>
      <div id="convenio-status"></div>
    </div>`;
  const cpfEl=$('convenio-cpf');
  if(cpfEl) cpfEl.addEventListener('input',e=>{e.target.value=formatCpf(e.target.value);});
}
function verificarConvenio(){
  const sel=$('conf-convenio');
  const cpf=($('convenio-cpf').value||'').trim();
  const status=$('convenio-status');
  const cobertoBox=$('convenio-coberto-box');
  const r=buscarConvenio(cpf, sel.value);
  if(r.ok){
    bookingState.convenioVerificado=true;
    status.innerHTML=`<div class="convenio-ok">✓ Convênio ${sel.value} verificado com sucesso.</div>`;
    if(cobertoBox){
      cobertoBox.style.display='block';
      cobertoBox.innerHTML=`<div class="pay-info-box">✅ Consulta coberta pelo convênio ${sel.value}. Nenhum pagamento é necessário — é só comparecer com o CPF e a carteirinha no dia.</div>`;
    }
  }else{
    bookingState.convenioVerificado=false;
    status.innerHTML=`<div class="convenio-erro">✕ ${r.motivo}</div>`;
    if(cobertoBox){ cobertoBox.style.display='none'; cobertoBox.innerHTML=''; }
  }
}

// ─── PAINEL DE PAGAMENTO (Pix / Cartão / Débito / Dinheiro) ──
function renderPaymentDetails(tipo){
  const box=$('payment-details-box');
  if(!box) return;
  const valor=parsePreco(bookingState.specPrice);

  if(tipo==='pix'){
    const codigo=gerarPayloadPix(valor, 'PC'+Date.now().toString().slice(-8));
    box.innerHTML=`
      <div class="pix-box">
        <div class="pix-qr" id="pix-qr-canvas"></div>
        <div class="pix-copia">
          <label>Pix Copia e Cola</label>
          <textarea id="pix-copia-texto" readonly>${codigo}</textarea>
          <button type="button" class="btn-outline" style="width:100%;margin-top:.5rem" onclick="copiarPix()">📋 Copiar código</button>
          <div id="pix-copia-feedback"></div>
        </div>
      </div>`;
    const qrDiv=$('pix-qr-canvas');
    if(qrDiv && window.QRCode){
      qrDiv.innerHTML='';
      new QRCode(qrDiv, { text:codigo, width:168, height:168, correctLevel:QRCode.CorrectLevel.M });
    }
  } else if(tipo==='credito' || tipo==='parcelado'){
    const parcelasOptions=[1,2,3,4,5,6].map(n=>{
      const val=(valor/n).toFixed(2).replace('.',',');
      return `<option value="${n}">${n}x de R$ ${val}${n===1?' à vista':' sem juros'}</option>`;
    }).join('');
    box.innerHTML=`
      <div class="card-box">
        <div class="pay-info-box" style="margin-bottom:1rem">💳 Ao confirmar, você será redirecionado para o <strong>Mercado Pago</strong> — um ambiente seguro e oficial — pra digitar os dados do cartão e concluir o pagamento.</div>
        ${tipo==='parcelado'?`<div class="form-group"><label>Parcelas</label><select id="card-parcelas">${parcelasOptions}</select></div>`:''}
        <div id="card-erro" class="error-msg"></div>
      </div>`;
  } else if(tipo==='debito'){
    box.innerHTML=`<div class="pay-info-box">💳 O pagamento no débito é feito presencialmente, na maquininha da clínica, no dia da sua consulta.</div>`;
  } else if(tipo==='dinheiro'){
    box.innerHTML=`<div class="pay-info-box">💵 O pagamento em dinheiro é feito presencialmente, na recepção da clínica, no dia da sua consulta.</div>`;
  } else {
    box.innerHTML='';
  }
}
function copiarPix(){
  const el=$('pix-copia-texto');
  el.select(); el.setSelectionRange(0,99999);
  try{
    navigator.clipboard.writeText(el.value);
    $('pix-copia-feedback').textContent='Código copiado!';
  }catch(e){
    document.execCommand('copy');
    $('pix-copia-feedback').textContent='Código copiado!';
  }
}
// ─── CALENDÁRIO ──────────────────────────────────────────
function changeMonth(d){
  bookingState.month+=d;
  if(bookingState.month>11){bookingState.month=0;bookingState.year++;}
  if(bookingState.month<0){bookingState.month=11;bookingState.year--;}
  renderCal();
}

function renderCal(){
  const {month,year,doctor}=bookingState;
  const lbl=$('cal-month-label');if(lbl)lbl.textContent=MONTHS[month]+' '+year;
  const head=$('cal-days-head');if(head)head.innerHTML=WDAYS.map(d=>`<div class="cal-day-label">${d}</div>`).join('');
  const first=new Date(year,month,1).getDay(), total=new Date(year,month+1,0).getDate();
  const today=new Date(), todayNorm=new Date(today.getFullYear(),today.getMonth(),today.getDate());
  const disp=doctor?datasDisponiveis(doctor,month,year):new Set();
  let html='';
  for(let i=0;i<first;i++) html+='<div></div>';
  for(let d=1;d<=total;d++){
    const dt=new Date(year,month,d);
    const dd=String(d).padStart(2,'0'),mm=String(month+1).padStart(2,'0');
    const ds=`${dd}/${mm}/${year}`;
    const disabled=dt<todayNorm||dt.getDay()===0||(doctor&&!disp.has(ds));
    const isTd=dt.toDateString()===today.toDateString();
    const cls=['cal-day',disabled?'disabled':'',isTd?'today':''].filter(Boolean).join(' ');
    html+=`<div class="${cls}" ${!disabled?`onclick="pickDay(${d},this)"`:''}>${d}</div>`;
  }
  const grid=$('cal-grid');if(grid)grid.innerHTML=html;
  renderTimes();
}

function pickDay(d,el){
  document.querySelectorAll('#cal-grid .cal-day').forEach(e=>e.classList.remove('selected'));
  if(el)el.classList.add('selected');
  const m=String(bookingState.month+1).padStart(2,'0'),dd=String(d).padStart(2,'0');
  bookingState.date=`${dd}/${m}/${bookingState.year}`;
  set('sum-date',bookingState.date);
  bookingState.time='';set('sum-time','—');
  const bn=$('btn-next-2');if(bn)bn.disabled=true;
  renderTimes();
}

function renderTimes(){
  const grid=$('times-grid');if(!grid)return;
  const {doctor,date}=bookingState;
  if(!date){grid.innerHTML='<p style="color:var(--muted);font-size:.8125rem;grid-column:1/-1">Selecione uma data primeiro.</p>';return;}
  const livres=slotsDiaSelecionado(doctor,date);
  grid.innerHTML=TODOS_SLOTS.map(t=>{
    const livre=livres.includes(t);
    return `<div class="time-slot${!livre?' unavail':''}" ${livre?`onclick="pickTime('${t}',this)"`:''}>${t}</div>`;
  }).join('');
}

function pickTime(t,el){
  document.querySelectorAll('.time-slot').forEach(e=>e.classList.remove('selected'));
  if(el)el.classList.add('selected');
  bookingState.time=t;set('sum-time',t);
  if(bookingState.date){const bn=$('btn-next-2');if(bn)bn.disabled=false;}
}

function nextStep(n){
  const prev=currentBookingStep;
  const sc=$('step-'+prev);if(sc)sc.classList.remove('active');
  const si=$('step-ind-'+prev);
  if(si){si.classList.remove('active');if(n>prev)si.classList.add('done');else si.classList.remove('done');}
  currentBookingStep=n;
  const nc=$('step-'+n);if(nc)nc.classList.add('active');
  const ni=$('step-ind-'+n);if(ni){ni.classList.add('active');ni.classList.remove('done');}
  if(n===3){
    set('conf-spec',bookingState.spec||'—');set('conf-doctor',bookingState.doctor);
    set('conf-date',bookingState.date||'—');set('conf-time',bookingState.time||'—');
    set('conf-price',bookingState.specPrice||'—');
    const convSel=$('conf-convenio');
    if(!convSel||convSel.value==='Particular') renderPaymentDetails((bookingState.pagamento||'Pix').toLowerCase());
  }
}

async function confirmBooking(){
  if(!currentUser){goto('screen-login');return;}
  const horariosOcup=horariosOcupados(bookingState.doctor,bookingState.date);
  if(horariosOcup.includes(bookingState.time)){showAlertModal('Este horário acabou de ser preenchido.');nextStep(2);renderCal();return;}
  if(horarioJaPassou(bookingState.date,bookingState.time)){showAlertModal('Esse horário já passou. Escolha outro.');nextStep(2);renderCal();renderTimes();return;}
  if(diaCheio(bookingState.doctor,bookingState.date)){showAlertModal('Médico sem vagas neste dia.');nextStep(2);renderCal();return;}
  const convenioEl=$('conf-convenio'), motivoEl=$('conf-motivo');
  const convenioEscolhido=convenioEl?convenioEl.value:'Particular';
  if(convenioEscolhido!=='Particular' && !bookingState.convenioVerificado){
    showAlertModal('Verifique o convênio pelo CPF antes de confirmar. Só aceitamos consultas por convênio depois da verificação.', null, 'Convênio não verificado');
    return;
  }
  const tipoPagamento=(bookingState.pagamento||'Pix').toLowerCase();
  const usaConvenio=convenioEscolhido!=='Particular';
  const ehCartao=tipoPagamento==='credito'||tipoPagamento==='parcelado';
  const pagaComMercadoPago=!usaConvenio && ehCartao;
  let parcelas=1;
  if(pagaComMercadoPago && tipoPagamento==='parcelado'){
    const parcEl=$('card-parcelas');
    parcelas=parcEl?parseInt(parcEl.value,10):1;
  }
  const pagamentoFinal=usaConvenio?'Convênio':(bookingState.pagamento||'Pix');
  const ehPresencial=ehPagamentoPresencial(pagamentoFinal);
  const pagamentoJaConfirmado=pagaComMercadoPago?false:!ehPresencial; // cartão só é confirmado depois do retorno do Mercado Pago
  const medicoObj=MEDICOS.find(m=>m.nome===bookingState.doctor);
  const { data:inserida, error:erroInsercao } = await sb.from('consultas').insert({
    paciente_id:currentUser.id, paciente_nome:currentUser.nome, paciente_cpf:currentUser.cpf, paciente_whatsapp:currentUser.whatsapp||'',
    medico_id:medicoObj?medicoObj.id:null, medico_nome:bookingState.doctor,
    especialidade:bookingState.spec, data:dataBRparaISO(bookingState.date), hora:bookingState.time, status:'agendada',
    convenio:convenioEscolhido, pagamento:pagamentoFinal, pagamento_confirmado:pagamentoJaConfirmado,
    parcelas:parcelas>1?parcelas:null,
    motivo:motivoEl&&motivoEl.value.trim()?motivoEl.value.trim():'',
    valor:usaConvenio?'Coberto pelo convênio':bookingState.specPrice,
  }).select().single();
  if(erroInsercao){ showAlertModal('Não foi possível agendar: '+erroInsercao.message); return; }
  const nova=mapConsultaDoSupabase(inserida);

  if(pagaComMercadoPago){
    const { data:pagamentoData, error:erroPagamento } = await sb.functions.invoke('criar-pagamento', {
      body: {
        consultaId: nova.id,
        valor: parsePreco(bookingState.specPrice),
        descricao: `${bookingState.spec} — ${bookingState.doctor}`,
        parcelas,
        pacienteNome: currentUser.nome,
        pacienteEmail: currentUser.email||'',
        siteUrl: window.location.origin + window.location.pathname,
      },
    });
    if(erroPagamento || !pagamentoData || !pagamentoData.init_point){
      showAlertModal('Não foi possível iniciar o pagamento. Tente novamente em instantes.');
      return;
    }
    window.location.href = pagamentoData.init_point;
    return;
  }
  set('suc-spec',bookingState.spec);set('suc-doc',bookingState.doctor);
  set('suc-dt',bookingState.date+' às '+bookingState.time);
  set('suc-prot',Math.floor(Math.random()*9000+1000));
  const wtsLink=$('suc-whatsapp');
  if(wtsLink) wtsLink.href=montarLinkWhatsAppConfirmacao(nova);
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  $('screen-success').classList.add('active');window.scrollTo(0,0);
}

const CLINICA_ENDERECO='Rua Mocóca, 101 – Carapicuíba, SP';
const CLINICA_WHATSAPP='5511992566807';
function montarLinkWhatsAppConfirmacao(consulta){
  const msg=`Olá! Gostaria de confirmar meu agendamento na Prime Clinic 👋\n\n`+
    `🩺 Tipo de consulta: ${consulta.especialidade}\n`+
    `👨‍⚕️ Médico(a): ${consulta.medico}\n`+
    `📅 Data e horário: ${consulta.data} às ${consulta.hora}\n`+
    `📍 Endereço: ${CLINICA_ENDERECO}\n\n`+
    `Paciente: ${consulta.pacienteNome}`;
  return `https://wa.me/${CLINICA_WHATSAPP}?text=${encodeURIComponent(msg)}`;
}

function montarLinkWhatsApp(consulta){
  const primeiroNome=(consulta.pacienteNome||'').split(' ')[0];
  const msg=`Olá ${primeiroNome}, tudo bem?\n\n`+
    `*Este é um lembrete da sua consulta, dia ${consulta.data} às ${consulta.hora} com o(a) ${consulta.medico}* 🩺\n`+
    `Confirmado?\n\n`+
    `*${CLINICA_ENDERECO}*\n`+
    `*Att. Prime Clinic*`;
  const numero=(consulta.pacienteWhatsapp||'').replace(/\D/g,'');
  return `https://wa.me/55${numero}?text=${encodeURIComponent(msg)}`;
}

function enviarLembrete(id){
  const c=DB.consultas.find(c=>c.id===id);
  if(!c) return;
  const numero=(c.pacienteWhatsapp||'').replace(/\D/g,'');
  if(numero.length<10){
    showAlertModal(`${c.pacienteNome} ainda não tem um WhatsApp cadastrado no perfil, então não é possível enviar o lembrete direto pra ele(a).`, null, 'Sem WhatsApp cadastrado');
    return;
  }
  window.open(montarLinkWhatsApp(c), '_blank', 'noopener');
}

// Restaura a sessão ao recarregar: o paciente sai do site para pagar no Mercado Pago e volta
async function restaurarSessao(){
  const { data:{ session } } = await sb.auth.getSession();
  if(!session) return;
  const { data:perfil } = await sb.from('profiles').select('*').eq('id',session.user.id).single();
  if(!perfil) return;
  currentUser={ id:session.user.id, email:session.user.email, nome:perfil.nome, cpf:perfil.cpf, role:perfil.role, crm:perfil.crm, especialidade:perfil.especialidade, whatsapp:perfil.whatsapp };
}

async function tratarRetornoMercadoPago(){
  const params=new URLSearchParams(window.location.search);
  const pagamento=params.get('pagamento');
  const consultaId=params.get('consulta');
  if(!pagamento||!consultaId) return;

  window.history.replaceState({},'',window.location.pathname);

  if(pagamento==='falha'){
    showAlertModal('O pagamento não foi concluído. Você pode tentar novamente pela tela de agendamento.', ()=>goto('screen-dashboard'), 'Pagamento não concluído');
    return;
  }
  if(pagamento==='pendente'){
    showAlertModal('Seu pagamento está sendo processado. Assim que for aprovado, sua consulta é confirmada automaticamente.', ()=>goto('screen-dashboard'), 'Pagamento pendente');
    return;
  }
  if(pagamento==='sucesso'){
    const paymentId=params.get('payment_id')||params.get('collection_id');
    if(!paymentId) return;
    const { data:confirmacao } = await sb.functions.invoke('confirmar-pagamento', { body:{ consultaId, paymentId } });
    const { data:consultaRow } = await sb.from('consultas').select('*').eq('id',consultaId).maybeSingle();
    if(consultaRow){
      const c=mapConsultaDoSupabase(consultaRow);
      set('suc-spec',c.especialidade);set('suc-doc',c.medico);
      set('suc-dt',c.data+' às '+c.hora);
      set('suc-prot',c.id);
      const wtsLink=$('suc-whatsapp'); if(wtsLink) wtsLink.href=montarLinkWhatsAppConfirmacao(c);
      document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
      $('screen-success').classList.add('active');window.scrollTo(0,0);
    }
    if(confirmacao&&!confirmacao.aprovado){
      showAlertModal('O pagamento ainda não foi confirmado pelo Mercado Pago. Isso pode levar alguns instantes — confira o painel "Minhas consultas" daqui a pouco.','','Aguardando confirmação');
    }
  }
}

document.addEventListener('DOMContentLoaded',async ()=>{
  ['reg-cpf'].forEach(id=>{const el=$(id);if(el)el.addEventListener('input',e=>{e.target.value=formatCpf(e.target.value);});});
  ['reg-whatsapp'].forEach(id=>{const el=$(id);if(el)el.addEventListener('input',e=>{e.target.value=formatPhone(e.target.value);});});
  ['login-email','login-pass'].forEach(id=>{const el=$(id);if(el)el.addEventListener('keydown',e=>{if(e.key==='Enter')doLogin();});});
  const now=new Date();
  bookingState={spec:'',specPrice:'',doctor:MEDICOS[0].nome,date:'',time:'',pagamento:'Pix',month:now.getMonth(),year:now.getFullYear()};
  renderCal();
  await restaurarSessao();
  await tratarRetornoMercadoPago();
});
